UIWelderSparkParticle=function(game,x,y){Phaser.Particle.call(this,game,x,y,game.cache.getBitmapData('welderspark'));this.kill();};UIWelderSparkParticle.prototype=Object.create(Phaser.Particle.prototype);UIWelderSparkParticle.prototype.constructor=UIWelderSparkParticle;UIWelderSparkParticle.prototype.onEmit=function(){var xx=Math.floor(Math.random()*UIWelderSparkParticle.spawnPoints.length);var randomSpawnPoint=UIWelderSparkParticle.spawnPoints[xx];this.x=UIWelderSparkParticle.tankIcon.world.x+randomSpawnPoint.x*UIWelderSparkParticle.tankIcon.width;this.y=UIWelderSparkParticle.tankIcon.world.y+randomSpawnPoint.y*UIWelderSparkParticle.tankIcon.height;this.body.bounce.setTo(0.5,0.7);};UIWelderSparkParticle.prototype.update=function(){this.rotation=this.game.math.angleBetween(this.body.velocity.x,this.body.velocity.y,1.0,0.0);this.alpha=Math.max(0.0,this.alpha-(0.008-Math.random()*0.001));};UIWelderSparkParticle.prototype.retire=function(){this.kill();};UIWelderSparkParticle.setSpawnPoints=function(tankIcon,spawnPointsOld,spawnPointsNew){UIWelderSparkParticle.spawnPoints=[];UIWelderSparkParticle.tankIcon=tankIcon;if(spawnPointsOld){UIWelderSparkParticle.spawnPoints=UIWelderSparkParticle.spawnPoints.concat(spawnPointsOld);}if(spawnPointsNew){UIWelderSparkParticle.spawnPoints=UIWelderSparkParticle.spawnPoints.concat(spawnPointsNew);}};